const ECONOMY_BASE6={fresh,makeStore,nextWeek,validateSave,weeklyFixed,companyValue,crewPay5,shiftWages5,propertyMarket5,buyOffice,buyRoaster,buyEstate,buyBakery5,roastProcessingCost5,bakeryFixed5,takeLoan,raiseCapital,repay,simulateEstates,openStore,buyEquipmentModel5,applyDesign5,upgradeRoaster,maintainRoaster,suggestShifts5,board,openingQuote5,takeGrowthLoan4,acquireRival};
