function ensureEconomy6(v){if(v.economy6===undefined)v.economy6={since:v.week,vatEscrow:0,corporateEscrow:0,vatPaid:0,corporatePaid:0,lossCarry:0,quarter:{start:v.week,profit:0,reserved:0},assets:[],history:[],loans:v.debt>0?[{id:"loan-inherited",amount:v.debt,started:v.week,paid:0,remaining:v.debt}]:[]};return v;}
fresh=function(...args){const v=ensureEconomy6(ECONOMY_BASE6.fresh(...args));if((args[0]||'sandbox')!=='sandbox')v.stores.forEach(foundingRoster6);if((args[0]||'sandbox')==='sandbox'){v.roasters[0].tenure6='contract';v.roasters[0].name='Praha · smluvní pražení';v.logs[0].detail='Kapitál 650 000 Kč, smluvní pražení a zásoby. Vlastní provozy kupuješ až z vydělaných peněz.';}return v;};
function foundingRoster6(s){if(s.franchise||!s.crew)return s;const old=s.daily.shifts.reduce((n,x)=>n+x,0),target=Math.max(3,Math.round(old*.8));s.daily.shifts=allocate5(target,s.daily.shifts);let units=s.crew.employees.reduce((n,p)=>n+p.contract,0);while(units>target){const last=s.crew.employees.at(-1),cut=Math.min(last.contract,units-target);last.contract-=cut;units-=cut;if(!last.contract)s.crew.employees.pop();}planCrew5(s);return s;}
