suggestShifts5=function(s){const counts=ECONOMY_BASE6.suggestShifts5(s);return allocate5(Math.max(3,Math.round(counts.reduce((n,x)=>n+x,0)*.8)),counts);};ensureEconomy6(state);if(state.week===1&&state.studio5.opening&&!state.stores.length){state.roasters[0].tenure6='contract';state.roasters[0].name='Praha · smluvní pražení';}
