nextWeek=function(){guard();if(!state.stores.length&&!(typeof hasOpeningWork6==='function'&&hasOpeningWork6()))throw Error("Nejdřív otevři první kavárnu.");ensureEconomy6(state);syncEconomicAssets6();for(const r of state.roasters)if(r.tenure6==='contract'){r.condition=100;r.staff=2*r.shifts;}const initial=state.cash,old=economyTurn6;economyTurn6={vat:0,storeNonCash:0,storePayroll:0,storeCosts:{},nonStore:null};try{const h=ECONOMY_BASE6.nextWeek(),f=state.economy6,non=economyTurn6.nonStore||economicNonStoreCosts6();for(const a of f.assets)a.accum=econRound6(Math.min(a.cost,a.accum+a.cost/a.life));const pretax=h.profit,q=f.quarter;q.profit+=pretax;const required=econRound6(Math.max(0,q.profit-f.lossCarry)*ECONOMY_RULES6.corporate),incomeTax=econRound6(required-q.reserved);q.reserved=required;f.corporateEscrow=required;state.cash-=incomeTax;h.profit=round(pretax-incomeTax);h.expenses=round(h.expenses+incomeTax);h.margin=h.revenue?h.profit/h.revenue:0;f.vatEscrow=econRound6(f.vatEscrow+economyTurn6.vat);let vatPaid=0,incomePaid=0;if(h.week%4===0){vatPaid=f.vatEscrow;f.vatPaid+=vatPaid;f.vatEscrow=0;}if(h.week%13===0){incomePaid=f.corporateEscrow;f.corporatePaid+=incomePaid;f.lossCarry=Math.max(0,f.lossCarry-q.profit);f.corporateEscrow=0;f.quarter={start:state.week,profit:0,reserved:0};}
 h.detail.localPayroll=round(non.regionalPayroll);let principal=0;for(const loan of f.loans){if(!loan.remaining)continue;const due=econRound6(Math.min(loan.remaining,loan.amount/260,state.debt));state.cash-=due;state.debt=econRound6(Math.max(0,state.debt-due));loan.remaining=econRound6(loan.remaining-due);loan.paid=econRound6(loan.paid+due);principal+=due;}f.loans=f.loans.filter(l=>l.remaining>.01);h.detail.employerCost+=round(economyTurn6.storePayroll);h.detail.incomeTax=incomeTax;h.detail.vatReserved=round(economyTurn6.vat);h.detail.capitalDepreciation+=round(economyTurn6.storeNonCash);h.detail.loanPrincipal=round(principal);h.cash=round(state.cash);h.cashChange=round(state.cash-initial);f.history.push({week:h.week,grossRetail:state.stores.filter(s=>!s.franchise).reduce((n,s)=>n+s.last.retailSales,0),netRevenue:h.revenue,operating:pretax,netProfit:h.profit,employer:non.payroll+economyTurn6.storePayroll,vat:economyTurn6.vat,vatPaid,incomeTax,incomePaid,principal,depreciation:non.depreciation+economyTurn6.storeNonCash,cash:state.cash,escrow:f.vatEscrow+f.corporateEscrow});f.history=f.history.slice(-52);refreshEconomicReports6(h);state.over=state.cash<0||state.sold===true;if(!state.history.slice(-4).every(x=>x.profit>0)){state.win=false;}return h;}finally{economyTurn6=old;}};
